import React, { useMemo, useState } from "react";

import {
  partitions,
  workers,
} from "../data/mockData";


function Partitions() {

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");


  /*
   * Find the worker currently assigned to a partition.
   */

  const getWorker = (workerId) => {
    return workers.find(
      (worker) => worker.id === workerId
    );
  };


  /*
   * Filter partitions.
   */

  const filteredPartitions = useMemo(() => {

    return partitions.filter((partition) => {

      const worker = getWorker(
        partition.workerId
      );


      const searchText = search.toLowerCase();


      const matchesSearch =
        partition.name
          .toLowerCase()
          .includes(searchText) ||

        String(partition.id)
          .includes(searchText) ||

        (
          worker &&
          worker.name
            .toLowerCase()
            .includes(searchText)
        );


      const matchesStatus =
        statusFilter === "all" ||
        partition.status === statusFilter;


      return (
        matchesSearch &&
        matchesStatus
      );

    });

  }, [search, statusFilter]);


  const activeCount = partitions.filter(
    (partition) =>
      partition.status === "active"
  ).length;


  const inactiveCount =
    partitions.length - activeCount;


  return (

    <div className="partitions-page">

      {/* ====================================================
          Header
      ==================================================== */}

      <div className="partitions-page-header">

        <div>

          <h1>
            Partitions
          </h1>

          <p>
            Monitor Kafka partitions and worker assignments
          </p>

        </div>


        <div className="partition-summary">

          <div className="summary-item">

            <span className="summary-dot healthy"></span>

            {activeCount} Active

          </div>


          {inactiveCount > 0 && (

            <div className="summary-item">

              <span className="summary-dot failed"></span>

              {inactiveCount} Inactive

            </div>

          )}

        </div>

      </div>


      {/* ====================================================
          Toolbar
      ==================================================== */}

      <div className="partitions-toolbar">

        <div className="partition-search">

          <span className="search-icon">
            ⌕
          </span>

          <input
            type="text"
            placeholder="Search partitions or workers..."
            value={search}
            onChange={(event) =>
              setSearch(event.target.value)
            }
          />

        </div>


        <div className="partition-filters">

          <button
            className={
              statusFilter === "all"
                ? "filter-button active"
                : "filter-button"
            }
            onClick={() =>
              setStatusFilter("all")
            }
          >
            All
          </button>


          <button
            className={
              statusFilter === "active"
                ? "filter-button active"
                : "filter-button"
            }
            onClick={() =>
              setStatusFilter("active")
            }
          >
            Active
          </button>


          <button
            className={
              statusFilter === "inactive"
                ? "filter-button active"
                : "filter-button"
            }
            onClick={() =>
              setStatusFilter("inactive")
            }
          >
            Inactive
          </button>

        </div>

      </div>


      {/* ====================================================
          Partition table
      ==================================================== */}

      <div className="partitions-table-container">

        <table className="partitions-table">

          <thead>

            <tr>

              <th>
                Partition
              </th>

              <th>
                Status
              </th>

              <th>
                Assigned Worker
              </th>

              <th>
                Consumer Lag
              </th>

              <th>
                Assignment
              </th>

            </tr>

          </thead>


          <tbody>

            {filteredPartitions.map(
              (partition) => {

                const worker =
                  getWorker(
                    partition.workerId
                  );


                return (

                  <tr
                    key={partition.id}
                  >

                    {/* Partition */}

                    <td>

                      <div className="partition-name">

                        <span className="partition-icon">
                          P
                        </span>

                        <div>

                          <strong>
                            {partition.name}
                          </strong>

                          <span>
                            ID: {partition.id}
                          </span>

                        </div>

                      </div>

                    </td>


                    {/* Status */}

                    <td>

                      <span
                        className={
                          partition.status === "active"
                            ? "partition-status active"
                            : "partition-status inactive"
                        }
                      >

                        <span className="status-dot"></span>

                        {partition.status}

                      </span>

                    </td>


                    {/* Worker */}

                    <td>

                      {worker ? (

                        <div className="assigned-worker">

                          <span className="worker-status-dot healthy"></span>

                          <span>
                            {worker.name}
                          </span>

                        </div>

                      ) : (

                        <span className="unassigned">
                          Unassigned
                        </span>

                      )}

                    </td>


                    {/* Lag */}

                    <td>

                      <span
                        className={
                          partition.lag > 35
                            ? "lag high"
                            : "lag"
                        }
                      >
                        {partition.lag}
                      </span>

                    </td>


                    {/* Assignment */}

                    <td>

                      <span className="assignment-state">

                        {worker
                          ? "Assigned"
                          : "Pending"}

                      </span>

                    </td>

                  </tr>

                );

              }
            )}

          </tbody>

        </table>


        {/* Empty state */}

        {filteredPartitions.length === 0 && (

          <div className="partitions-empty">

            <div className="empty-icon">
              ⌕
            </div>

            <h3>
              No partitions found
            </h3>

            <p>
              Try changing your search or filter.
            </p>

          </div>

        )}

      </div>


      {/* ====================================================
          Footer
      ==================================================== */}

      <div className="partitions-footer">

        Showing{" "}
        <strong>
          {filteredPartitions.length}
        </strong>{" "}
        of{" "}
        <strong>
          {partitions.length}
        </strong>{" "}
        partitions

      </div>

    </div>

  );
}


export default Partitions;
